 function saveDrawing(){try{const form=readDrawing(),kind=tool,points=C.clone(draft),old=appendId;const isRoute=['route','arrow'].includes(kind);const id=old||C.freshId(isRoute?plan.routes:plan.areas,isRoute?'route-':'area-');const data={id,name:form.name||(isRoute?'Route ':'Area ')+id.split('-').pop(),phaseId:form.phaseId,style:form.style};if(kind==='arrow')data.style.pattern='arrow';if(kind==='circle'){data.kind='circle';data.center=points[0];data.radius=C.distance(points[0],points[1])}else{data.points=points;if(!isRoute)data.kind=kind}const ok=commit(p=>{if(old)Object.assign(p.routes.find(r=>equal(r.id,old)),data);else(isRoute?p.routes:p.areas).push(data)},'Drawing saved. Select it to edit style or drag its handles.');if(ok){cancelTool();picks.clear();selection={kind:isRoute?'route':'area',id};picks.set(selection.kind+':'+id,selection);selectionUI();fillSelection();renderMap();renderDrawingList()}}catch(e){status(e.message,true)}}
