 function mapClick(e){if(Date.now()<suppressClick)return;let p=validPoint(e.latlng);if(!p)return;if(tool&&tool!=='measure')p=snapPoint(p);lastPoint=p;inspect(p);if(tool==='order-destination'){const done=orderPointPicker;orderPointPicker=null;cancelTool();done?.(C.clone(p));return;}if(tool==='marker'){try{const u=readUnit();u.id=C.freshId(plan.orderOfBattle,'unit-');u.position=p;if(commit(d=>d.orderOfBattle.push(u),'Unit placed. Drag it to refine its position.')){cancelTool();picks.clear();picks.set('unit:'+u.id,{kind:'unit',id:u.id});selection={kind:'unit',id:u.id};selectionUI();fillSelection();renderMap();renderTree()}}catch(err){status(err.message,true)}}else if(tool==='measure'){measure.push(p);if(measure.length>2)measure=[p];drawMeasure();if(measure.length===2){tool=null;$('map').style.cursor='';all('[data-tool]').forEach(b=>b.classList.remove('active'));status('Measurement fixed. Start Ruler again to measure another pair.')}}else if(tool){if(!draft.length||C.distance(draft[draft.length-1],p)>0.01)draft.push(p);draftUI();previewDraft();if(['rectangle','circle'].includes(tool)&&draft.length===2)saveDrawing()}else if(picks.size&&!e.originalEvent?.ctrlKey)selectItem(null,null)}
