 function endBox(e){if(!boxStart)return;const start=boxStart;boxStart=null;boxEl?.remove();boxEl=null;const end=map.mouseEventToContainerPoint(e);if(start.point.distanceTo(end)<5)return;suppressClick=Date.now()+200;const bounds=L.latLngBounds(map.containerPointToLatLng(start.point),map.containerPointToLatLng(end));if(!start.add)picks.clear();for(const {kind,o}of visibleObjects()){let inside;if(PlannerPreferences.get().selectionBox==='touching')inside=E.touches(o,kind,{west:bounds.getWest(),east:bounds.getEast(),south:bounds.getSouth(),north:bounds.getNorth()});else if(kind==='unit')inside=bounds.contains(o.position);else if(o.kind==='circle')inside=bounds.contains(L.latLngBounds([o.center.lat-o.radius,o.center.lng-o.radius],[o.center.lat+o.radius,o.center.lng+o.radius]));else inside=o.points.every(p=>bounds.contains(p));if(inside)picks.set(kind+':'+o.id,{kind,id:o.id})}syncSelection();}
