 function drawMeasure(cursor){groups.measure.clearLayers();const points=cursor?[measure[0],cursor]:measure;if(points.length===1)L.circleMarker(points[0],{radius:5,color:'#fff',pane:'editPane'}).addTo(groups.measure);if(points.length<2)return;L.polyline(points,{color:'#fff',weight:2,dashArray:'4 5',interactive:false,pane:'editPane'}).addTo(groups.measure);const distance=C.distance(points[0],points[1]),bearing=C.bearing(points[0],points[1]);$('measureReadout').textContent=PlannerPreferences.distance(distance)+' · '+(bearing==null?'bearing —':bearing.toFixed(1)+'°')+' · '+C.grid(points[0],plan.view.gridDigits)+' → '+C.grid(points[1],plan.view.gridDigits)}
