 function lineOptions(style,pane,interactive=true){return {pane,color:style.color,weight:style.width*Number(PlannerPreferences.get().lineScale),dashArray:style.pattern==='dashed'?'10 8':style.pattern==='dotted'?'1 9':null,lineCap:'round',fillColor:style.color,fillOpacity:style.opacity,interactive,bubblingMouseEvents:false}}
 function arrows(points,style,group,pane){for(let i=1;i<points.length;i++){const a=map.latLngToLayerPoint(points[i-1]),b=map.latLngToLayerPoint(points[i]);const dx=b.x-a.x,dy=b.y-a.y,len=Math.hypot(dx,dy);if(len<6)continue;const size=Math.min(18+style.width,len*.45),ux=dx/len,uy=dy/len;const left=L.point(b.x-ux*size-uy*size*.5,b.y-uy*size+ux*size*.5),right=L.point(b.x-ux*size+uy*size*.5,b.y-uy*size-ux*size*.5);L.polyline([map.layerPointToLatLng(left),points[i],map.layerPointToLatLng(right)],{color:style.color,weight:style.width*Number(PlannerPreferences.get().lineScale),interactive:false,pane,lineCap:'round'}).addTo(group)}}
 function geometry(d,kind,group,interactive=true){const pane=kind==='route'?'routePane':'areaPane',opts=lineOptions(d.style,pane,interactive);let layer;if(kind==='route')layer=L.polyline(d.points,opts);else if(d.kind==='circle')layer=L.circle(d.center,{...opts,radius:d.radius});else if(d.kind==='rectangle')layer=L.rectangle(d.points,opts);else layer=L.polygon(d.points,opts);layer.addTo(group);if(selected(kind,d.id)&&interactive)layer.setStyle({color:'#FFFFFF',weight:d.style.width+2});if(d.style.pattern==='arrow'&&kind==='route')arrows(d.points,d.style,interactive?groups.arrows:group,pane);if(interactive){layer.bindTooltip(esc(d.name+' · '+phaseName(d.phaseId)));layer.on('click',e=>{if(tool)mapClick(e);else selectItem(kind,d.id,e.originalEvent?.ctrlKey||e.originalEvent?.metaKey)})}return layer}
