 function handle(p,fn){const m=L.marker(p,{pane:'editPane',icon:L.divIcon({className:'vertex-icon',iconSize:[14,14],iconAnchor:[7,7]}),draggable:true,bubblingMouseEvents:false}).addTo(groups.handles);m.on('click',()=>{});m.on('dragend',e=>{const p=e.target.getLatLng();fn(snapPoint(p))});return m}
 function renderHandles(){groups.handles.clearLayers();const d=drawingSelected();if(!d||d.locked||!C.visible(plan,d)||!$('editVertices').checked||!plan.view.layers[selection.kind==='route'?'routes':'areas'])return;const collection=selection.kind==='route'?'routes':'areas',id=d.id;if(d.kind==='circle'){handle(d.center,p=>commit(x=>x.areas.find(a=>equal(a.id,id)).center=p,'Circle moved.'));handle({lat:d.center.lat,lng:d.center.lng+d.radius},p=>commit(x=>x.areas.find(a=>equal(a.id,id)).radius=C.distance(d.center,p),'Radius changed.'))}else d.points.forEach((p,i)=>handle(p,pos=>commit(x=>x[collection].find(o=>equal(o.id,id)).points[i]=pos,'Waypoint moved.')))}
