 $('applyDrawing').onclick=()=>{const d=drawingSelected();if(!d)return;try{const values=readDrawing(),kind=selection.kind;if(kind==='area'&&values.style.pattern==='arrow')throw Error('Arrowheads apply to paths. Choose solid, dashed or dotted for an area.');commit(p=>{const o=p[kind==='route'?'routes':'areas'].find(x=>equal(x.id,d.id));Object.assign(o,values);if(o.kind==='circle')o.radius=Number($('circleRadius').value)},'Drawing style updated.')}catch(e){status(e.message,true)}};
